Read all dates from column A of the active sheet, compute the full daily range from the minimum to maximum date, and subtract the existing dates. Write the sorted missing dates as datetime values into C2:C13, clearing the region first. Save the workbook.

```python
import shutil
import openpyxl
from datetime import datetime, date, timedelta

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws_vals = vals.active
ws = wb[ws_vals.title]

def to_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, (int, float)):
        try:
            from openpyxl.utils.datetime import from_excel
            return from_excel(value).date()
        except Exception:
            return None
    if isinstance(value, str):
        s = value.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y", "%Y/%m/%d"):
            try:
                return datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return None

existing = set()
for row in range(2, ws_vals.max_row + 1):
    d = to_date(ws_vals.cell(row=row, column=1).value)
    if d is not None:
        existing.add(d)

if existing:
    start = min(existing)
    end = max(existing)
    missing = []
    d = start
    while d <= end:
        if d not in existing:
            missing.append(datetime(d.year, d.month, d.day))
        d += timedelta(days=1)
else:
    missing = []

for row in range(2, 14):
    cell = ws.cell(row=row, column=3)
    cell.value = None
    cell.number_format = "yyyy-mm-dd"

for i, dt in enumerate(missing[:12], start=2):
    ws.cell(row=i, column=3).value = dt

print("missing_count:", len(missing))
if missing:
    print("first:", missing[0].date(), "last:", missing[-1].date())

wb.save(OUT)
